//! Exceptions dictionary lookup (rules.md section 6). Tables are generated by build.rs.

#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) enum Kind {
    Word,
    Stem,
}

include!(concat!(env!("OUT_DIR"), "/dict_gen.rs"));

/// A hit: number of key characters consumed (= source characters, the key is normalised 1:1) and the target.
pub(crate) struct Hit {
    pub n: usize,
    pub target: &'static str,
}

/// Exact `word`/`stem` key first, else the longest `stem` key that is a prefix of `key`.
pub(crate) fn find(table: &'static [(&'static str, &'static str, Kind)], key: &str) -> Option<Hit> {
    let i = table.partition_point(|e| e.0 <= key);
    if i > 0 && table[i - 1].0 == key {
        return Some(Hit {
            n: key.chars().count(),
            target: table[i - 1].1,
        });
    }
    let first = key.chars().next()?;
    // Prefix keys sort before `key` and share its first char, so only that bucket is walked.
    for e in table[..i].iter().rev() {
        if !e.0.starts_with(first) {
            break;
        }
        if e.2 == Kind::Stem && key.starts_with(e.0) {
            return Some(Hit {
                n: e.0.chars().count(),
                target: e.1,
            });
        }
    }
    None
}

pub(crate) fn acro(
    table: &'static [(&'static str, &'static str)],
    word: &str,
) -> Option<&'static str> {
    table
        .binary_search_by(|e| e.0.cmp(word))
        .ok()
        .map(|i| table[i].1)
}

pub(crate) fn keep(word: &str) -> bool {
    KEEP.binary_search(&word).is_ok()
}
